<body>
<div class="wrap">

  <h1>Ba(OH)₂ 溶液滴加稀硫酸：导电能力为什么先降后升？</h1>
  <p class="sub">拖动滑块，或直接在曲线图上横向拖动，观察「溶液里的离子」和「导电能力」怎样同步变化。</p>

  <div class="facts">
    <span class="chip"><b>已知</b>向一定体积的 Ba(OH)₂ 溶液中滴加稀硫酸</span>
    <span class="chip"><b>测得</b>导电能力随时间先降后升，a 点最低</span>
    <span class="chip"><b>判断</b>A、B、C、D 四个说法</span>
  </div>

  <div class="stage">
    <div class="panel">
      <h2>溶液里的离子（微观示意）</h2>
      <canvas id="simCanvas"></canvas>

      <div class="meter-wrap">
        <span>导电能力</span>
        <div class="meter"><i id="meterFill"></i></div>
        <span class="mono" id="meterVal" style="width:42px;text-align:right;">100%</span>
      </div>

      <div class="ctrl">
        <button class="btn" id="playBtn">播放</button>
        <input type="range" id="xSlider" min="0" max="3" step="0.01" value="0" aria-label="滴加量">
        <span class="mono" id="xVal" style="width:34px;text-align:right;">0.00</span>
      </div>

      <div class="legend" id="legend"></div>
      <div class="eqline" id="eqLine"></div>
    </div>

    <div class="panel">
      <h2>导电能力 — 滴加量曲线</h2>
      <canvas id="chartCanvas"></canvas>
      <div class="status" id="statusText">拖动滑块，看看曲线上的点怎样移动。</div>
    </div>
  </div>

  <h2 class="sec-title">四个说法，哪个成立？点一点，用曲线验证</h2>
  <div class="opt-grid" id="optGrid"></div>
  <div class="feedback" id="feedback"></div>

</div>

<script>
(function(){
  'use strict';

  /* ============================================================
     一、化学模型：用「摩尔电导率 × 离子浓度」估算相对导电能力
     摩尔电导率（近似值，只用于相对比较）：
       H⁺ 350, OH⁻ 200, Ba²⁺ 127, SO₄²⁻ 160, Na⁺ 50, K⁺ 73.5, Mg²⁺ 106
     ============================================================ */
  const LAM = { H:350, OH:200, Ba:127, SO4:160, Na:50, K:73.5, Mg:106 };
  const YMAX = 620;          // 纵轴上限
  const ION_R = 12;          // 离子小球半径

  const ION_STYLE = {
    Ba:  { fill:'#4f7cff', label:'Ba'  },
    OH:  { fill:'#18bfa0', label:'OH'  },
    H:   { fill:'#ff7a45', label:'H'   },
    SO4: { fill:'#9b6bff', label:'SO4' },
    Na:  { fill:'#f0a01e', label:'Na'  },
    K:   { fill:'#e0559b', label:'K'   },
    Mg:  { fill:'#33a353', label:'Mg'  }
  };
  const ION_TEXT = {
    Ba:'Ba²⁺', OH:'OH⁻', H:'H⁺', SO4:'SO₄²⁻', Na:'Na⁺', K:'K⁺', Mg:'Mg²⁺'
  };

  /* 各情景：kappa(x) 返回相对导电能力；counts(x) 返回画面中的离子个数 */
  const SCEN = {
    original: {
      name:'Ba(OH)₂ + 稀硫酸',
      eq:'Ba(OH)₂ + H₂SO₄ → BaSO₄↓ + 2H₂O',
      eqX: 1,
      kappa(x){
        const V = 1 + x;
        return x <= 1
          ? (LAM.Ba*(1-x) + LAM.OH*2*(1-x)) / V
          : (LAM.H*2*(x-1) + LAM.SO4*(x-1)) / V;
      },
      counts(x){
        const left = Math.max(0, 1-x);
        return {
          Ba: 6*left,
          OH: 12*left,
          H: Math.min(16, 12*Math.max(0, x-1)),
          SO4: Math.min(10, 6*Math.max(0, x-1))
        };
      },
      precip(x){ return Math.min(Math.max(x,0), 1); },
      legend: ['Ba','OH','H','SO4'],
      note(x){
        if (x < 0.97) return '正在滴加：Ba²⁺ 与 SO₄²⁻ 结合成 BaSO₄ 沉淀，H⁺ 与 OH⁻ 结合成水，溶液中的自由离子不断减少 → 导电能力下降。';
        if (x < 1.03) return '恰好完全反应（图中的 a 点）：溶液中几乎没有自由离子，导电能力降到最低。';
        return '硫酸过量：溶液中重新出现大量 H⁺ 和 SO₄²⁻ → 导电能力回升。';
      }
    },

    naoh: {
      name:'NaOH + 稀硫酸',
      eq:'2NaOH + H₂SO₄ → Na₂SO₄ + 2H₂O',
      eqX: 0.5,
      kappa(x){
        const V = 1 + x;
        return x <= 0.5
          ? (LAM.Na + LAM.OH*(1-2*x) + LAM.SO4*x) / V
          : (LAM.Na + LAM.H*(2*x-1) + LAM.SO4*x) / V;
      },
      counts(x){
        return {
          Na: 6,
          OH: Math.max(0, 6 - 12*x),
          SO4: Math.min(14, 6*x),
          H: Math.min(18, 12*Math.max(0, x-0.5))
        };
      },
      precip(){ return 0; },
      legend: ['Na','OH','SO4','H'],
      note(x){
        if (x < 0.46) return 'H⁺ 中和 OH⁻，同时引入 SO₄²⁻；但 Na⁺ 始终留在溶液中，导电能力降不到接近 0。';
        if (x < 0.58) return '恰好中和：溶液中仍有 Na⁺ 和 SO₄²⁻，导电能力明显不为 0 —— 最低点不像原图那样贴近横轴。';
        return '硫酸过量：H⁺ 增加，导电能力继续上升。';
      }
    },

    khso4: {
      name:'Ba(OH)₂ + KHSO₄',
      eq:'Ba(OH)₂ + 2KHSO₄ → BaSO₄↓ + K₂SO₄ + 2H₂O',
      eqX: 2,
      kappa(x){
        const V = 1 + x;
        const Ba  = Math.max(0, 1 - x);
        const SO4 = Math.max(0, x - 1);
        const OH  = Math.max(0, 2 - x);
        const H   = Math.max(0, x - 2);
        return (LAM.Ba*Ba + LAM.SO4*SO4 + LAM.OH*OH + LAM.H*H + LAM.K*x) / V;
      },
      counts(x){
        return {
          Ba: 6*Math.max(0, 1-x),
          OH: 12*Math.max(0, 1 - x/2),
          K:  Math.min(14, 6*x),
          SO4:Math.min(10, 6*Math.max(0, x-1)),
          H:  Math.min(10, 6*Math.max(0, x-2))
        };
      },
      precip(x){ return Math.min(Math.max(x,0), 1); },
      legend: ['Ba','OH','K','SO4','H'],
      note(){
        return 'KHSO₄ 每加入一份就带入 K⁺，而 K⁺ 不会被消耗，所以最低点处溶液仍然能导电 —— 最低点明显高于 0，与原图不符。';
      }
    },

    mgso4: {
      name:'Ba(OH)₂ + MgSO₄',
      eq:'Ba(OH)₂ + MgSO₄ → BaSO₄↓ + Mg(OH)₂↓',
      eqX: 1,
      kappa(x){
        const V = 1 + x;
        return x <= 1
          ? (LAM.Ba*(1-x) + LAM.OH*2*(1-x)) / V
          : (LAM.Mg*(x-1) + LAM.SO4*(x-1)) / V;
      },
      counts(x){
        const left = Math.max(0, 1-x);
        return {
          Ba: 6*left,
          OH: 12*left,
          Mg:  Math.min(10, 6*Math.max(0, x-1)),
          SO4: Math.min(10, 6*Math.max(0, x-1))
        };
      },
      precip(x){ return Math.min(Math.max(x,0), 1); },
      legend: ['Ba','OH','Mg','SO4'],
      note(x){
        if (x < 0.97) return 'Ba²⁺ + SO₄²⁻ → BaSO₄↓；Mg²⁺ + 2OH⁻ → Mg(OH)₂↓，两种离子同时被除去 → 导电能力下降。';
        if (x < 1.03) return '恰好完全反应：溶液中几乎没有自由离子，导电能力降到最低。';
        return 'MgSO₄ 过量：Mg²⁺ 与 SO₄²⁻ 增多，导电能力回升（上升得比硫酸慢，但形状一致）。';
      }
    }
  };

  /* ============================================================
     二、选项
     ============================================================ */
  const OPTIONS = [
    { id:'A', ok:false, scen:null,
      text:'AB段溶液的导电能力减弱，说明生成的BaSO₄不是电解质',
      fb:'BaSO₄ 是强电解质，只是难溶。AB 段导电能力减弱，真正的原因是 Ba²⁺ 和 OH⁻ 被不断消耗、浓度减小——这一点在左侧粒子图里看得很清楚。' },
    { id:'B', ok:false, scen:'naoh',
      text:'实验时用NaOH溶液代替Ba(OH)₂溶液也能得到该曲线',
      fb:'换用 NaOH：反应后 Na⁺、SO₄²⁻ 仍留在溶液中，导电能力不会降到接近 0，曲线的最低点明显抬高，形状不同。' },
    { id:'C', ok:false, scen:'khso4',
      text:'实验时用稀KHSO₄溶液代替稀硫酸也能得到该曲线',
      fb:'换用 KHSO₄：每加一份就带入 K⁺，反应结束后溶液中仍有 K⁺、SO₄²⁻，最低点明显不为 0，最低点位置也右移。' },
    { id:'D', ok:true, scen:'mgso4',
      text:'实验时用稀MgSO₄溶液代替稀硫酸也能得到该曲线',
      fb:'换用 MgSO₄：Ba²⁺ + SO₄²⁻ → BaSO₄↓，Mg²⁺ + 2OH⁻ → Mg(OH)₂↓，两种离子都被除去，最低点接近 0；过量的 MgSO₄ 又使导电能力回升。曲线形状与原图一致。' }
  ];

  /* ============================================================
     三、状态与 DOM
     ============================================================ */
  const state = { scene:'original', x:0, playing:false };

  const simCanvas   = document.getElementById('simCanvas');
  const chartCanvas = document.getElementById('chartCanvas');
  const simCtx      = simCanvas.getContext('2d');
  const chartCtx    = chartCanvas.getContext('2d');
  const simSize     = { w:0, h:0 };
  const chartSize   = { w:0, h:0 };

  const slider   = document.getElementById('xSlider');
  const xVal     = document.getElementById('xVal');
  const meterFill= document.getElementById('meterFill');
  const meterVal = document.getElementById('meterVal');
  const statusEl = document.getElementById('statusText');
  const legendEl = document.getElementById('legend');
  const eqLine   = document.getElementById('eqLine');
  const playBtn  = document.getElementById('playBtn');
  const optGrid  = document.getElementById('optGrid');
  const feedback = document.getElementById('feedback');

  /* ============================================================
     四、粒子系统
     ============================================================ */
  const sim = { ions: [] };

  function makeIon(type, box){
    const r = ION_R;
    return {
      type,
      x: box.x0 + r + Math.random()*Math.max(1, box.x1-box.x0-2*r),
      y: box.y0 + r + Math.random()*Math.max(1, box.y1-box.y0-2*r),
      vx: (Math.random()-0.5)*28,
      vy: (Math.random()-0.5)*28,
      a: 0, alive:true, r
    };
  }

  const ALL_TYPES = ['Ba','OH','H','SO4','Na','K','Mg'];

  function updateIons(dt, counts, box){
    for (let i=0;i<ALL_TYPES.length;i++){
      const t = ALL_TYPES[i];
      const want = Math.round(counts[t] || 0);
      let aliveN = 0;
      for (let k=0;k<sim.ions.length;k++){
        const p = sim.ions[k];
        if (p.type === t && p.alive) aliveN++;
      }
      if (aliveN < want){
        const add = Math.min(want - aliveN, 3);
        for (let k=0;k<add;k++) sim.ions.push(makeIon(t, box));
      } else if (aliveN > want){
        let ex = aliveN - want;
        for (let k=0;k<sim.ions.length && ex>0;k++){
          const p = sim.ions[k];
          if (p.type === t && p.alive){ p.alive = false; ex--; }
        }
      }
    }

    for (let i=0;i<sim.ions.length;i++){
      const p = sim.ions[i];
      p.a += ((p.alive ? 1 : 0) - p.a) * Math.min(1, dt*8);
      p.x += p.vx*dt;
      p.y += p.vy*dt;
      const r = p.r;
      if (p.x < box.x0+r){ p.x = box.x0+r; p.vx = Math.abs(p.vx); }
      if (p.x > box.x1-r){ p.x = box.x1-r; p.vx = -Math.abs(p.vx); }
      if (p.y < box.y0+r){ p.y = box.y0+r; p.vy = Math.abs(p.vy); }
      if (p.y > box.y1-r){ p.y = box.y1-r; p.vy = -Math.abs(p.vy); }
    }

    const next = [];
    for (let i=0;i<sim.ions.length;i++){
      const p = sim.ions[i];
      if (p.alive || p.a > 0.02) next.push(p);
    }
    sim.ions = next;
  }

  /* 沉淀位置的伪随机固定分布 */
  const SPOTS = (function(){
    let s = 20240517;
    const rnd = function(){ s = (s*1103515245 + 12345) & 0x7fffffff; return s / 0x7fffffff; };
    const arr = [];
    for (let i=0;i<24;i++) arr.push({ fx: rnd(), fy: rnd(), r: 2.1 + rnd()*2.4 });
    return arr;
  })();

  /* ============================================================
     五、绘图：烧杯 + 离子
     ============================================================ */
  function simBox(w, h){
    const bx0 = w*0.10, bx1 = w*0.90;
    const byTop = h*0.20, byBot = h*0.965;
    const liquidTop = byTop + (byBot-byTop)*0.15;
    return {
      bx0:bx0, bx1:bx1, byTop:byTop, byBot:byBot, liquidTop:liquidTop,
      x0: bx0+20, x1: bx1-20,
      y0: liquidTop+20, y1: byBot-28
    };
  }

  function drawSim(dt, counts){
    const w = simSize.w, h = simSize.h;
    if (w < 2 || h < 2) return;
    const ctx = simCtx;
    ctx.clearRect(0,0,w,h);

    const B = simBox(w,h);
    const bx0 = B.bx0, bx1 = B.bx1, byTop = B.byTop, byBot = B.byBot, liquidTop = B.liquidTop;

    /* 烧杯外形 */
    ctx.beginPath();
    ctx.moveTo(bx0, byTop);
    ctx.lineTo(bx0, byBot-13);
    ctx.quadraticCurveTo(bx0, byBot, bx0+13, byBot);
    ctx.lineTo(bx1-13, byBot);
    ctx.quadraticCurveTo(bx1, byBot, bx1, byBot-13);
    ctx.lineTo(bx1, byTop);
    ctx.strokeStyle = '#b3c2d6';
    ctx.lineWidth = 2.5;
    ctx.lineJoin = 'round';
    ctx.stroke();

    /* 液体 */
    ctx.beginPath();
    ctx.moveTo(bx0+1.5, liquidTop);
    ctx.lineTo(bx0+1.5, byBot-13);
    ctx.quadraticCurveTo(bx0+1.5, byBot-1.5, bx0+13, byBot-1.5);
    ctx.lineTo(bx1-13, byBot-1.5);
    ctx.quadraticCurveTo(bx1-1.5, byBot-1.5, bx1-1.5, byBot-13);
    ctx.lineTo(bx1-1.5, liquidTop);
    ctx.closePath();
    const lg = ctx.createLinearGradient(0, liquidTop, 0, byBot);
    lg.addColorStop(0, '#f2f8ff');
    lg.addColorStop(1, '#d9ebfd');
    ctx.fillStyle = lg;
    ctx.fill();

    /* 液面线 */
    ctx.beginPath();
    ctx.moveTo(bx0+2, liquidTop);
    ctx.lineTo(bx1-2, liquidTop);
    ctx.strokeStyle = '#a9cdf0';
    ctx.lineWidth = 2;
    ctx.stroke();

    /* 沉淀 */
    const sc = SCEN[state.scene];
    const amt = sc.precip ? sc.precip(state.x) : 0;
    const nSpot = Math.round(amt * SPOTS.length);
    for (let i=0;i<nSpot;i++){
      const s = SPOTS[i];
      const px = bx0 + 24 + s.fx*(bx1-bx0-48);
      const py = byBot - 24 - s.fy*10;
      ctx.beginPath();
      ctx.arc(px, py, s.r, 0, Math.PI*2);
      ctx.fillStyle = 'rgba(255,255,255,.96)';
      ctx.fill();
      ctx.strokeStyle = 'rgba(126,160,205,.85)';
      ctx.lineWidth = 1;
      ctx.stroke();
    }

    /* 离子 */
    updateIons(dt, counts, B);
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    for (let i=0;i<sim.ions.length;i++){
      const p = sim.ions[i];
      const st = ION_STYLE[p.type];
      if (!st) continue;
      const al = Math.max(0, Math.min(1, p.a));
      if (al < 0.03) continue;
      const rr = p.r * (0.35 + 0.65*al);
      ctx.globalAlpha = al;
      ctx.beginPath();
      ctx.arc(p.x, p.y, rr, 0, Math.PI*2);
      ctx.fillStyle = st.fill;
      ctx.fill();
      if (al > 0.55 && rr > 8){
        ctx.fillStyle = '#fff';
        ctx.font = '600 9px system-ui,"PingFang SC",sans-serif';
        ctx.fillText(st.label, p.x, p.y+0.5);
      }
      ctx.globalAlpha = 1;
    }

    /* 滴管 */
    const tx = w*0.5;
    const tubeH = Math.max(18, byTop - 14);
    ctx.fillStyle = 'rgba(160,182,210,.45)';
    ctx.fillRect(tx-8, byTop - tubeH - 8, 16, tubeH + 8);
    ctx.fillStyle = 'rgba(160,182,210,.85)';
    ctx.fillRect(tx-14, byTop - tubeH - 16, 28, 10);

    if (state.x > 0.003){
      const t = (performance.now()/650) % 1;
      const dy = (byTop - tubeH) + t * (tubeH + 20);
      ctx.beginPath();
      ctx.ellipse(tx, dy, 3.6, 5, 0, 0, Math.PI*2);
      ctx.fillStyle = 'rgba(120,170,235,.85)';
      ctx.fill();
    }
  }

  /* ============================================================
     六、绘图：曲线
     ============================================================ */
  const PAD = { l:50, r:16, t:16, b:38 };

  function chartGeom(){
    const w = chartSize.w, h = chartSize.h;
    const px0 = PAD.l, px1 = w - PAD.r, py0 = h - PAD.b, py1 = PAD.t;
    return {
      w:w, h:h, px0:px0, px1:px1, py0:py0, py1:py1,
      X: function(v){ return px0 + (v/3)*(px1-px0); },
      Y: function(v){ return py0 - (v/YMAX)*(py0-py1); }
    };
  }

  function plotCurve(ctx, G, fn, color, width, dash){
    ctx.save();
    ctx.setLineDash(dash || []);
    ctx.beginPath();
    ctx.strokeStyle = color;
    ctx.lineWidth = width;
    ctx.lineJoin = 'round';
    ctx.lineCap = 'round';
    for (let i=0;i<=200;i++){
      const xv = i/200*3;
      let yv = fn(xv);
      if (!isFinite(yv)) yv = 0;
      yv = Math.max(0, Math.min(YMAX, yv));
      const px = G.X(xv), py = G.Y(yv);
      if (i===0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
    }
    ctx.stroke();
    ctx.restore();
  }

  function drawChart(){
    const w = chartSize.w, h = chartSize.h;
    if (w < 2 || h < 2) return;
    const ctx = chartCtx;
    ctx.clearRect(0,0,w,h);

    const G = chartGeom();
    const px0 = G.px0, px1 = G.px1, py0 = G.py0, py1 = G.py1;

    /* 网格 */
    ctx.strokeStyle = '#eef3f9';
    ctx.lineWidth = 1;
    for (let v=0; v<=600; v+=150){
      ctx.beginPath();
      ctx.moveTo(px0, G.Y(v));
      ctx.lineTo(px1, G.Y(v));
      ctx.stroke();
    }

    /* 坐标轴 */
    ctx.strokeStyle = '#8496ad';
    ctx.lineWidth = 1.6;
    ctx.beginPath();
    ctx.moveTo(px0, py1-10);
    ctx.lineTo(px0, py0);
    ctx.lineTo(px1+10, py0);
    ctx.stroke();

    ctx.fillStyle = '#8496ad';
    ctx.beginPath();
    ctx.moveTo(px0-5, py0+9);
    ctx.lineTo(px0+5, py0+9);
    ctx.lineTo(px0, py0-1);
    ctx.closePath();
    ctx.fill();

    ctx.beginPath();
    ctx.moveTo(px1+2, py0-5);
    ctx.lineTo(px1+2, py0+5);
    ctx.lineTo(px1+12, py0);
    ctx.closePath();
    ctx.fill();

    /* 轴标题 */
    ctx.save();
    ctx.translate(14, (py0+py1)/2);
    ctx.rotate(-Math.PI/2);
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = '#5b6779';
    ctx.font = '12px system-ui,"PingFang SC",sans-serif';
    ctx.fillText('导电能力', 0, 0);
    ctx.restore();

    ctx.fillStyle = '#5b6779';
    ctx.font = '12px system-ui,"PingFang SC",sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'top';
    ctx.fillText('时间 / 滴加量', (px0+px1)/2, py0+20);

    /* 原题曲线（对照） */
    if (state.scene !== 'original'){
      plotCurve(ctx, G, SCEN.original.kappa, '#c8d3e2', 2, [5,5]);
    }

    /* 当前曲线 */
    plotCurve(ctx, G, SCEN[state.scene].kappa, '#2b6cff', 2.8, null);

    /* 原图的 a 点 */
    if (state.scene === 'original'){
      const ax = G.X(1);
      ctx.save();
      ctx.setLineDash([3,4]);
      ctx.strokeStyle = '#c2cfe0';
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.moveTo(ax, py0);
      ctx.lineTo(ax, G.Y(SCEN.original.kappa(1)) + 2);
      ctx.stroke();
      ctx.restore();

      ctx.fillStyle = '#8b9ab0';
      ctx.font = 'italic 14px Georgia,serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'top';
      ctx.fillText('a', ax, py0 + 5);
    }

    /* 与画布对应的当前点 */
    const cur = SCEN[state.scene].kappa(state.x);
    const cx = G.X(state.x), cy = G.Y(Math.max(0, Math.min(YMAX, cur)));

    ctx.save();
    ctx.setLineDash([4,4]);
    ctx.strokeStyle = 'rgba(43,108,255,.32)';
    ctx.lineWidth = 1.2;
    ctx.beginPath();
    ctx.moveTo(cx, py0);
    ctx.lineTo(cx, cy);
    ctx.stroke();
    ctx.restore();

    ctx.beginPath();
    ctx.arc(cx, cy, 6.2, 0, Math.PI*2);
    ctx.fillStyle = '#2b6cff';
    ctx.fill();
    ctx.strokeStyle = '#fff';
    ctx.lineWidth = 2.2;
    ctx.stroke();

    /* 曲线关键点标注 */
    ctx.font = '600 12.5px system-ui,"PingFang SC",sans-serif';
    ctx.fillStyle = '#5b6779';
    ctx.textAlign = 'left';
    ctx.textBaseline = 'bottom';
    ctx.fillText('A', G.X(0.16)+2, G.Y(SCEN[state.scene].kappa(0.16)) - 8);

    const lowX = state.scene === 'khso4' ? 2 : (state.scene === 'naoh' ? 0.5 : 1);
    const lowY = SCEN[state.scene].kappa(lowX);
    ctx.textAlign = 'center';
    ctx.fillText('B', G.X(lowX), G.Y(lowY) - 12);

    ctx.textAlign = 'left';
    ctx.textBaseline = 'bottom';
    ctx.fillText('C', G.X(2.55)+2, G.Y(SCEN[state.scene].kappa(2.55)) - 10);
  }

  /* ============================================================
     七、界面同步
     ============================================================ */
  function syncLegend(){
    const sc = SCEN[state.scene];
    let html = '';
    for (let i=0;i<sc.legend.length;i++){
      const t = sc.legend[i];
      html += '<span><i style="background:'+ION_STYLE[t].fill+'"></i>'+ION_TEXT[t]+'</span>';
    }
    if (sc.precip && sc.precip(1) > 0){
      html += '<span><i style="background:#fff;border:1px solid #9fb0c6"></i>沉淀</span>';
    }
    legendEl.innerHTML = html;
    eqLine.innerHTML = sc.eq.replace(/→/g, '<span class="arrow">→</span>');
  }

  let lastStatus = -999;
  function syncUI(){
    const sc = SCEN[state.scene];
    const k = sc.kappa(state.x);
    const pct = Math.max(0, Math.min(100, k / 527 * 100));

    meterFill.style.width = pct.toFixed(1) + '%';
    meterVal.textContent = Math.round(pct) + '%';
    xVal.textContent = state.x.toFixed(2);

    const note = sc.note(state.x);
    if (note !== statusEl.textContent) statusEl.textContent = note;

    const nearLow = Math.abs(state.x - sc.eqX) < 0.06;
    statusEl.classList.toggle('hot', nearLow);

    if (slider.value !== String(state.x)){
      // 避免与用户拖动冲突：只在播放时由外部同步
    }
  }

  /* ============================================================
     八、渲染循环
     ============================================================ */
  let lastT = performance.now();

  function loop(now){
    let dt = (now - lastT) / 1000;
    lastT = now;
    if (dt > 0.06) dt = 0.06;

    if (state.playing){
      state.x += dt * 0.55;
      if (state.x >= 3){ state.x = 3; state.playing = false; updatePlayBtn(); }
      slider.value = state.x;
    }

    const counts = SCEN[state.scene].counts(state.x);
    drawSim(dt, counts);
    drawChart();
    syncUI();

    requestAnimationFrame(loop);
  }

  /* ============================================================
     九、尺寸
     ============================================================ */
  function resize(){
    const dpr = Math.min(window.devicePixelRatio || 1, 2);

    let r = simCanvas.getBoundingClientRect();
    simSize.w = Math.max(1, Math.round(r.width));
    simSize.h = Math.max(1, Math.round(r.height));
    simCanvas.width  = Math.round(simSize.w * dpr);
    simCanvas.height = Math.round(simSize.h * dpr);
    simCtx.setTransform(dpr,0,0,dpr,0,0);

    r = chartCanvas.getBoundingClientRect();
    chartSize.w = Math.max(1, Math.round(r.width));
    chartSize.h = Math.max(1, Math.round(r.height));
    chartCanvas.width  = Math.round(chartSize.w * dpr);
    chartCanvas.height = Math.round(chartSize.h * dpr);
    chartCtx.setTransform(dpr,0,0,dpr,0,0);
  }

  window.addEventListener('resize', resize);

  /* ============================================================
     十、交互
     ============================================================ */
  function setX(v){
    state.x = Math.max(0, Math.min(3, v));
    slider.value = state.x;
  }

  slider.addEventListener('input', function(){
    state.playing = false;
    updatePlayBtn();
    setX(parseFloat(slider.value));
  });

  function updatePlayBtn(){
    playBtn.textContent = state.playing ? '暂停' : '播放';
  }

  playBtn.addEventListener('click', function(){
    if (state.playing){
      state.playing = false;
    } else {
      if (state.x >= 2.995) setX(0);
      state.playing = true;
    }
    updatePlayBtn();
  });

  /* 在曲线上横向拖动 */
  let dragging = false;

  function xFromEvent(e){
    const rect = chartCanvas.getBoundingClientRect();
    const G = chartGeom();
    const local = e.clientX - rect.left;
    const v = (local - G.px0) / (G.px1 - G.px0) * 3;
    return v;
  }

  chartCanvas.addEventListener('pointerdown', function(e){
    dragging = true;
    state.playing = false;
    updatePlayBtn();
    try { chartCanvas.setPointerCapture(e.pointerId); } catch(err){}
    setX(xFromEvent(e));
  });

  chartCanvas.addEventListener('pointermove', function(e){
    if (!dragging) return;
    setX(xFromEvent(e));
  });

  chartCanvas.addEventListener('pointerup', function(e){
    dragging = false;
    try { chartCanvas.releasePointerCapture(e.pointerId); } catch(err){}
  });

  chartCanvas.addEventListener('pointercancel', function(){ dragging = false; });

  /* 选项卡片 */
  let activeOpt = null;

  function buildOptions(){
    let html = '';
    for (let i=0;i<OPTIONS.length;i++){
      const o = OPTIONS[i];
      html += '<button class="opt" data-id="'+o.id+'" type="button">'
            +   '<span class="ltr">'+o.id+'</span>'
            +   '<span class="txt">'+o.text+'</span>'
            + '</button>';
    }
    optGrid.innerHTML = html;

    const btns = optGrid.querySelectorAll('.opt');
    for (let i=0;i<btns.length;i++){
      btns[i].addEventListener('click', function(){
        const id = this.getAttribute('data-id');
        selectOption(id);
      });
    }
  }

  function selectOption(id){
    const o = OPTIONS.filter(function(x){ return x.id === id; })[0];
    if (!o) return;

    activeOpt = id;

    /* 卡片状态 */
    const btns = optGrid.querySelectorAll('.opt');
    for (let i=0;i<btns.length;i++){
      const b = btns[i];
      const on = b.getAttribute('data-id') === id;
      b.classList.toggle('on', on);
      const old = b.querySelector('.res');
      if (old) old.remove();
      if (on){
        const tag = document.createElement('span');
        tag.className = 'res ' + (o.ok ? 'ok' : 'no');
        tag.textContent = o.ok ? '成立' : '不成立';
        b.appendChild(tag);
      }
    }

    /* 反馈 */
    feedback.className = 'feedback show ' + (o.ok ? 'ok' : 'no');
    feedback.innerHTML = '<b>' + (o.ok ? '正确。' : '错误。') + '</b>' + o.fb;

    /* 曲线场景 */
    state.playing = false;
    updatePlayBtn();

    if (o.scen){
      state.scene = o.scen;
      setX(1.5);
    } else {
      state.scene = 'original';
      setX(1.0);
    }

    syncLegend();
  }

  /* ============================================================
     十一、启动
     ============================================================ */
  buildOptions();
  syncLegend();
  resize();
  syncLegend();
  requestAnimationFrame(function(t){
    lastT = t;
    requestAnimationFrame(loop);
  });

  /* 首次尺寸可能在字体加载后变化 */
  setTimeout(resize, 60);
  setTimeout(resize, 300);

})();
</script>
</body>
